<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/../global/connection.php';require_once __DIR__.'/qa-http-client.php';
if(!str_ends_with(DB,'_qa'))throw new RuntimeException('Use una base _qa.');
$http=new AppQaHttpClient(getenv('APPU_QA_URL')?:'http://127.0.0.1:8765',DB);$key='QA-IDH-'.bin2hex(random_bytes(4));$product=null;$documents=[];$failed=false;
function inventoryHttpAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
try{
 $warehouse=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();inventoryHttpAssert($warehouse>0,'Falta un almacén QA activo.');
 $pdo->prepare("INSERT INTO tbl_product(code,brand,name,description,stock_quantity,unit_price,unit_value,active_status)VALUES(?,'QA','Artículo documento HTTP','Temporal',0,10,'UND',1)")->execute([$key]);$product=(int)$pdo->lastInsertId();
 $base=['action'=>'create','document_type'=>'ENTRY','warehouse_id'=>$warehouse,'document_date'=>date('Y-m-d'),'reason'=>'Entrada HTTP QA','external_reference'=>$key];
 foreach([['quantity'=>0.0001,'unit_cost'=>5],['quantity'=>1.0001,'unit_cost'=>5],['quantity'=>1,'unit_cost'=>-1]] as $invalidLine){[$status]=$http->request('/modules/inventory/documents.php',array_merge($base,['lines'=>json_encode([array_merge(['product_id'=>$product],$invalidLine)])]));inventoryHttpAssert($status===422,'Se aceptó cantidad/costo inválido de inventario.');}
 [$status,$created]=$http->request('/modules/inventory/documents.php',array_merge($base,['lines'=>json_encode([['product_id'=>$product,'quantity'=>10,'unit_cost'=>5,'lot_number'=>$key.'-L1','expiration_date'=>date('Y-m-d',strtotime('+180 days'))]])]));inventoryHttpAssert($status===200,'No creó la entrada: '.json_encode($created));$entry=(int)$created['document']['id'];$documents[]=$entry;
 [$status,$detail]=$http->request('/modules/inventory/documents.php?action=detail&id='.$entry);inventoryHttpAssert($status===200&&$detail['document']['document_type']==='ENTRY'&&count($detail['lines'])===1&&(float)$detail['lines'][0]['inventory_value']===50.0,'No se recuperó íntegra la entrada.');
 [$status,$list]=$http->request('/modules/inventory/documents.php?document_type=ENTRY&search='.urlencode($key));inventoryHttpAssert($status===200&&count($list['documents'])===1&&(int)$list['documents'][0]['id']===$entry,'La entrada no aparece en Buscar.');
 $stock=$pdo->prepare('SELECT quantity,inventory_value FROM tbl_warehouse_stock WHERE warehouse_id=? AND product_id=?');$stock->execute([$warehouse,$product]);$row=$stock->fetch();inventoryHttpAssert((float)$row['quantity']===10.0&&(float)$row['inventory_value']===50.0,'La entrada no valorizó existencias.');
 $issuePayload=array_merge($base,['document_type'=>'ISSUE','reason'=>'Salida HTTP QA','lines'=>json_encode([['product_id'=>$product,'quantity'=>3]])]);
 [$status,$created]=$http->request('/modules/inventory/documents.php',$issuePayload);inventoryHttpAssert($status===200,'No creó la salida: '.json_encode($created));$issue=(int)$created['document']['id'];$documents[]=$issue;
 $stock->execute([$warehouse,$product]);$row=$stock->fetch();inventoryHttpAssert((float)$row['quantity']===7.0&&(float)$row['inventory_value']===35.0,'La salida no descargó cantidad/costo.');
 [$status]=$http->request('/modules/inventory/documents.php',array_merge($issuePayload,['lines'=>json_encode([['product_id'=>$product,'quantity'=>8]])]));inventoryHttpAssert($status===422,'Se permitió salida superior al disponible.');
 [$status]=$http->request('/modules/inventory/documents.php',['action'=>'cancel','document_id'=>$entry,'cancellation_reason'=>'Intento con salida activa HTTP']);inventoryHttpAssert($status===422,'Se permitió anular entrada con salida posterior activa.');
 [$status,$report]=$http->request('/modules/reportes/inventario.php?warehouse_id='.$warehouse);inventoryHttpAssert($status===200,'No carga reporte de inventario.');$rows=array_values(array_filter($report['stock'],fn($x)=>(int)$x['id']===$product));inventoryHttpAssert(count($rows)===1&&(float)$rows[0]['inventory_value']===35.0,'El reporte no refleja el valor posterior a la salida.');
 foreach([$issue,$entry] as $id){[$status,$result]=$http->request('/modules/inventory/documents.php',['action'=>'cancel','document_id'=>$id,'cancellation_reason'=>'Reversión integral HTTP QA']);inventoryHttpAssert($status===200,'No anuló documento '.$id.': '.json_encode($result));}
 $stock->execute([$warehouse,$product]);$row=$stock->fetch();inventoryHttpAssert((float)$row['quantity']===0.0&&(float)$row['inventory_value']===0.0,'La reversión no dejó cantidad y valor en cero.');$lot=$pdo->prepare('SELECT SUM(quantity) FROM tbl_product_lot WHERE product_id=?');$lot->execute([$product]);inventoryHttpAssert((float)$lot->fetchColumn()===0.0,'La reversión no restauró los lotes.');
 echo "PASS HTTP inventory entry issue retrieval search precision valuation lots overissue protection and reversals\n";
}catch(Throwable $e){fwrite(STDERR,'FAIL inventory document HTTP: '.$e->getMessage().PHP_EOL);$failed=true;}
finally{
 if($pdo->inTransaction())$pdo->rollBack();$pdo->beginTransaction();foreach($documents as $id){$pdo->prepare("DELETE FROM tbl_document_status_history WHERE document_type='inventory_document' AND document_id=?")->execute([$id]);$pdo->prepare("DELETE FROM tbl_inventory_lot_application WHERE source_type='inventory_document' AND source_id=?")->execute([$id]);$pdo->prepare("DELETE FROM tbl_warehouse_movement WHERE source_type='inventory_document' AND source_id=?")->execute([$id]);$pdo->prepare('DELETE FROM tbl_inventory_document_detail WHERE inventory_document_id=?')->execute([$id]);$pdo->prepare('DELETE FROM tbl_inventory_document WHERE id=?')->execute([$id]);}if($product){$pdo->prepare('DELETE FROM tbl_product_lot WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_warehouse_stock WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_product WHERE id=?')->execute([$product]);}$pdo->commit();
}exit($failed?1:0);
